package com.mygdx.game.views;
import com.badlogic.gdx.graphics.Texture; import com.badlogic.gdx.graphics.g2d.SpriteBatch; import com.mygdx.game.GameSettings;
public class MovingBackgroundView extends View {private final Texture texture;private int firstY,secondY=GameSettings.SCREEN_HEIGHT;private int speed=2;public MovingBackgroundView(String p){super(0,0,GameSettings.SCREEN_WIDTH,GameSettings.SCREEN_HEIGHT);texture=new Texture(p);}public void move(){firstY-=speed;secondY-=speed;if(firstY<=-GameSettings.SCREEN_HEIGHT)firstY=GameSettings.SCREEN_HEIGHT;if(secondY<=-GameSettings.SCREEN_HEIGHT)secondY=GameSettings.SCREEN_HEIGHT;}public void draw(SpriteBatch b){b.draw(texture,0,firstY,GameSettings.SCREEN_WIDTH,GameSettings.SCREEN_HEIGHT);b.draw(texture,0,secondY,GameSettings.SCREEN_WIDTH,GameSettings.SCREEN_HEIGHT);}public void dispose(){texture.dispose();}}
